/**
 * Report 178 («сборка + патрон… бронежилеты и их плиты»): what a boss carries and how his armour is plated, from the game's
 * bot loadouts (about fifteen per bot). Generated by scripts/bosses/boss-gear.mjs into bossGear.json; PvP and PvE list
 * the same loadouts. The Gallery shows it in «Вооружение» and «Броня» (src/gallery/BossInfoPanel.tsx).
 */
import type { Bilingual } from './bossInfo'
import data from './bossGear.json'
import retinueData from './bossRetinue.json'

/** [min, max] armour class; one class when three of four plates have it. */
export type ClassRange = readonly [number, number]

export interface BossGearItem { id: string; name: Bilingual }
export interface BossGearWeapon extends BossGearItem { ammo: BossGearItem[] }

export interface BossGearGroup {
  /** The maps of this kit, when the boss's kit differs by map (Black Division, The Wedge). */
  maps?: string[]
  /** This kit is on every map but the other groups' (Black Division's heavy kit). */
  elsewhere?: boolean
  weapons: BossGearWeapon[]
  /** Body armour and armoured rigs, the most worn first. */
  armor: BossGearItem[]
  /** Share of the loadouts with body armour, 0–1. */
  armored: number
  plates: { front?: ClassRange; back?: ClassRange; side?: ClassRange }
  helmet?: ClassRange
  helmetId?: string
  helmeted: number
  /** A face cover with armour (Tagilla's welding masks). */
  face?: ClassRange
}

/** `guards`: all the guards' kit as one (no longer shown: «Свита» below names each kind). */
export interface BossGear { groups: BossGearGroup[]; guards?: Omit<BossGearGroup, 'maps'> }

const GEAR = data as unknown as Record<string, BossGear>

export function bossGear(key: string): BossGear | undefined {
  return GEAR[key]
}

/** How many of one kind of guard come with the boss on these maps. */
export interface RetinueCount { min: number; max: number; maps: string[] }
/** One kind of guard (owner, 20.11.2026: «какая свита, сколько человек, какая броня, оружие и какие у них патроны бывают»). */
export type RetinueMember = Partial<Omit<BossGearGroup, 'maps' | 'elsewhere'>> & {
  name: Bilingual
  counts: RetinueCount[]
  /** The Goons: this one's kit is on his own page. */
  ref?: string
}
/** `squad`: the boss walks with equals (the Goons), not guards. */
export interface BossRetinue { squad?: boolean; members: RetinueMember[] }

const RETINUE = retinueData as unknown as Record<string, BossRetinue>

/** The boss's retinue (scripts/bosses/boss-gear.mjs → bossRetinue.json), from the game's bot data. */
export function bossRetinue(key: string): BossRetinue | undefined {
  return RETINUE[key]
}

/** A guard's kit: his own loadouts, or the page he refers to. */
export function retinueGear(member: RetinueMember): Omit<BossGearGroup, 'maps'> | undefined {
  if (member.ref) return GEAR[member.ref]?.groups[0]
  return member.weapons && member.armor && member.plates ? member as Omit<BossGearGroup, 'maps'> : undefined
}

/** [fewest, most] of one kind, or of the whole retinue, over the maps. */
export function memberSize(member: RetinueMember): ClassRange {
  return [Math.min(...member.counts.map((count) => count.min)), Math.max(...member.counts.map((count) => count.max))]
}

export function retinueSize(retinue: BossRetinue): ClassRange {
  const maps = new Set(retinue.members.flatMap((member) => member.counts.flatMap((count) => count.maps)))
  let fewest = Infinity
  let most = 0
  for (const map of maps) {
    const here = retinue.members.map((member) => member.counts.find((count) => count.maps.includes(map))).filter((count) => count !== undefined)
    fewest = Math.min(fewest, here.reduce((sum, count) => sum + count.min, 0))
    most = Math.max(most, here.reduce((sum, count) => sum + count.max, 0))
  }
  return maps.size ? [fewest, most] : [0, 0]
}

/** «6», «4–5». */
export function classLabel(range: ClassRange): string {
  return range[0] === range[1] ? String(range[0]) : `${range[0]}–${range[1]}`
}
